import functools
import inspect
import types
from typing import ForwardRef, Any, Callable
from fastapi.dependencies.utils import get_typed_signature

def test_wrapped_function_forward_reference():
    module = types.ModuleType("my_module")

    class B:
        pass
    module.B = B

    def func(x: "B"):
        return x
    module.func = func

    def wrapper(f):
        @functools.wraps(f)
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(module.func)

    try:
        sig = get_typed_signature(wrapped_func)
        param_x = sig.parameters["x"]
        assert param_x.annotation is module.B
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_function_forward_reference()
'
